sys_script.script:
(function executeRule(current, previous) {

    function recalcRP(rpId) {
        if (!rpId) return;
        var ph = 0, ah = 0;
        var ga = new GlideAggregate('x_2316178_contin_0_employee_work_time');
        ga.addQuery('resource_plan', rpId);
        ga.addAggregate('SUM', 'planned_hours');
        ga.addAggregate('SUM', 'actual_hours');
        ga.query();
        if (ga.next()) {
            ph = parseFloat(ga.getAggregate('SUM', 'planned_hours') || 0);
            ah = parseFloat(ga.getAggregate('SUM', 'actual_hours') || 0);
        }
        var rp = new GlideRecord('x_2316178_contin_0_resource_plan');
        if (rp.get(rpId)) {
            rp.setValue('planned_hours', ph);
            rp.setValue('actual_hours', ah);
            rp.setWorkflow(false);
            rp.autoSysFields(false);
            rp.update();
        }
    }

    // Current parent RP
    var rpId = current.getValue('resource_plan');
    recalcRP(rpId);

    // If RP reference changed (re-assignment), recalculate old parent
    var oldRpId = (previous) ? previous.getValue('resource_plan') : '';
    if (oldRpId && oldRpId != rpId) {
        recalcRP(oldRpId);
    }

})(current, previous);
